import{_ as d,o as e,c as o,ag as c}from"./chunks/framework.CPvOxTBX.js";const b=JSON.parse('{"title":"键盘快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/keyboard-shortcuts.md","filePath":"zh/guide/keyboard-shortcuts.md","lastUpdated":1794229303000}'),a={name:"zh/guide/keyboard-shortcuts.md"};function r(l,t,n,h,i,s){return e(),o("div",null,t[0]||(t[0]=[c(`<h1 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h1><p>词悦的快捷键沿用 <a href="https://github.com/xiaoyifang/goldendict-ng" target="_blank" rel="noreferrer">GoldenDict-ng</a> 与 <a href="https://ebstudio.info/manual/EBWin4/EBWin4.html" target="_blank" rel="noreferrer">EBWin</a>、<a href="https://ebstudio.info/manual/EBMac/index.php" target="_blank" rel="noreferrer">EBMac</a> 的习惯：在其它词典里已经用顺手的键，在这里沿袭。</p><p>其中大部分<strong>仅限桌面端</strong>，因为Android版Flutter对激活键盘快捷键的焦点有问题。在 Android 上，除了少数快捷键，大部分快捷键都会因为焦点不知道跑哪去了，而不能稳定地激活。不过好在会用到键盘输入的安卓设备也有限——通常只有GPD Win Max、壹号游侠这样的UMPC上的Waydroid，某些自带键盘的安卓平板、手机会用到快捷键。而对UMPC来说，可以直接使用桌面版词悦。</p><h2 id="两个层级" tabindex="-1">两个层级 <a class="header-anchor" href="#两个层级" aria-label="Permalink to &quot;两个层级&quot;">​</a></h2><p>与词典有关的快捷键分两层：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ctrl+\`  /  Ctrl+1…9      分组：查词时用哪些词典</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └── Alt+0…9       词典：看哪一部词典的结果</span></span>
<span class="line"><span>                            Alt+0 = AI 解释，Alt+1…9 = 第 1…9 部词典</span></span>
<span class="line"><span>                            Alt+PgUp / Alt+PgDn = 上一个 / 下一个标签</span></span></code></pre></div><h2 id="查词" tabindex="-1">查词 <a class="header-anchor" href="#查词" aria-label="Permalink to &quot;查词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>F</code></td><td>把焦点移进搜索框</td></tr><tr><td><code>Esc</code></td><td>把焦点移进搜索框，<strong>并选中框里的文字</strong>，直接输入即可覆盖；再按一次回到词条</td></tr><tr><td>选中文字后按 <code>Enter</code></td><td>查选中的文字（见下）</td></tr><tr><td>选中文字后按 <code>Ctrl</code>+<code>Enter</code></td><td>在新标签页里查，相当于对链接按 <code>Ctrl</code>+点击</td></tr></tbody></table><p>宽窗口里有两个搜索框：左栏的那个，和词条标题栏里的那个。<code>Ctrl</code>+<code>F</code> 和 <code>Esc</code> 会落到你最后用过的那个，跟着你在窗口里走动，而不是每次都落在左边那个。</p><h3 id="查选中的文字" tabindex="-1">查选中的文字 <a class="header-anchor" href="#查选中的文字" aria-label="Permalink to &quot;查选中的文字&quot;">​</a></h3><p>在释义里选中一个词或一个短语，按 <code>Enter</code> 即可查词。这是 EBWin、EBMac 的做法，在桌面端这也是目前唯一的选词查词途径——释义页的右键菜单是 Chromium 自带的，只提供复制和检查元素。</p><p>「选中再按回车查询」比「直接双击一个单词查询」好用，因为在那些不用空格分词的语言里，双击能选到啥就只能看人品了；而且即便是英语这样的语言，有时也会遇到复合词和短语动词，直接双击查不到：</p><table tabindex="0"><thead><tr><th>语言</th><th>需要查询的词汇</th><th>单击选中整个单词</th></tr></thead><tbody><tr><td>德语</td><td><code>Bundesbankdirektor</code> 里的 <code>Bundesbank</code></td><td><code>Bundesbankdirektor</code></td></tr><tr><td>日语</td><td><code>日本語辞典</code> 里的 <code>日本語</code></td><td><code>日本語辞典</code></td></tr><tr><td>汉语</td><td><code>现代汉语词典</code> 里的 <code>汉语</code></td><td><code>现代汉语词典</code></td></tr><tr><td>英语</td><td><code>throw away</code></td><td><code>throw</code> 或者 <code>away</code></td></tr></tbody></table><p>在 Android 上，长按菜单里也有同样的查词项，旁边是复制和朗读；用鼠标右键点一个词也会选中它，菜单里的「查询」查的就是这个词。</p><h2 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h2><p>词悦里有三种标签，很容易混。</p><h3 id="单词标签" tabindex="-1">单词标签 <a class="header-anchor" href="#单词标签" aria-label="Permalink to &quot;单词标签&quot;">​</a></h3><p>顶部那排类似浏览器的标签，每个标签放一个词。</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>T</code></td><td>新建标签</td></tr><tr><td><code>Ctrl</code>+<code>W</code></td><td>关闭当前标签</td></tr><tr><td><code>Ctrl</code>+<code>Tab</code></td><td>下一个标签</td></tr><tr><td><code>Ctrl</code>+<code>Shift</code>+<code>Tab</code></td><td>上一个标签</td></tr><tr><td><code>Ctrl</code>+<code>PgDn</code> / <code>Ctrl</code>+<code>PgUp</code></td><td>下一个 / 上一个标签</td></tr></tbody></table><p>在单词本里，无论窄屏的全屏词页，还是宽屏的左右分栏，都能用 <code>←</code> / <code>→</code> 翻到上一个 / 下一个词（焦点需在词条区，不在搜索框）。两种布局都会在标题处显示「第 N / M 个」并带左右箭头按钮。</p><h3 id="词典分组" tabindex="-1">词典分组 <a class="header-anchor" href="#词典分组" aria-label="Permalink to &quot;词典分组&quot;">​</a></h3><p>分组决定查词时用哪些词典。分组按创建顺序列在窗口顶部的菜单里，快捷键也按这个顺序编号。</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code> + 反引号</td><td>切到第一个分组，即默认分组</td></tr><tr><td><code>Ctrl</code>+<code>1</code> … <code>Ctrl</code>+<code>9</code></td><td>切到第二个到第十个分组</td></tr></tbody></table><p>超出分组数量的数字不做任何事。切换之后，当前屏幕上的词会用新分组的词典重新查一遍。</p><h3 id="词典标签" tabindex="-1">词典标签 <a class="header-anchor" href="#词典标签" aria-label="Permalink to &quot;词典标签&quot;">​</a></h3><p>词典切换样式为<strong>标签式</strong>时，每部词典在释义区里有一个标签，数字键用来挑其中之一。</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Alt</code>+<code>1</code> … <code>Alt</code>+<code>9</code></td><td>显示第 1 到第 9 部词典</td></tr><tr><td><code>Alt</code>+<code>0</code></td><td>显示 AI 解释（需要开启该功能）</td></tr><tr><td><code>Alt</code>+<code>PgUp</code></td><td>显示上一个词典标签</td></tr><tr><td><code>Alt</code>+<code>PgDn</code></td><td>显示下一个词典标签</td></tr></tbody></table><p>到头会绕回另一端（和 <code>Ctrl</code>+<code>Tab</code> 的单词标签一样）。开启 AI 解释时，AI 标签也在这串标签里。相对切换不受 9 部的数量限制，第 10 部往后的词典也能到达。</p><p><strong>展开式</strong>下没有这些标签，这组键完全不做任何事。</p><h2 id="朗读" tabindex="-1">朗读 <a class="header-anchor" href="#朗读" aria-label="Permalink to &quot;朗读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>R</code></td><td>朗读当前词；正在朗读时再按一次则停止</td></tr><tr><td><code>Ctrl</code>+<code>Shift</code>+<code>S</code></td><td>停止播放</td></tr><tr><td><code>Alt</code>+<code>↑</code> / <code>Alt</code>+<code>↓</code></td><td>在历史记录里选上一个 / 下一个词</td></tr><tr><td><code>Alt</code>+<code>←</code> / <code>Alt</code>+<code>→</code></td><td>在词条历史里后退 / 前进</td></tr><tr><td><code>PgDn</code> / <code>PgUp</code></td><td>展开式下翻页</td></tr></tbody></table><h2 id="缩放释义" tabindex="-1">缩放释义 <a class="header-anchor" href="#缩放释义" aria-label="Permalink to &quot;缩放释义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code>+= / <code>Ctrl</code>++</td><td>放大释义</td></tr><tr><td><code>Ctrl</code>+-</td><td>缩小释义</td></tr><tr><td><code>Ctrl</code>+<code>0</code></td><td>恢复默认大小</td></tr></tbody></table><p>只有释义会被缩放，窗口的其它部分保持原样。缩放级别会被记住，重启后依然有效；<a href="/Ciyue/zh/guide/appearance.html">词典外观</a> 里也有对应的滑块。</p><p>大多数键盘上 <code>Ctrl</code>+= 和 <code>Ctrl</code>++ 是同一个键，两者都绑定了，按哪个都行。</p><h2 id="其它页面" tabindex="-1">其它页面 <a class="header-anchor" href="#其它页面" aria-label="Permalink to &quot;其它页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th><th>位置</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>Enter</code></td><td>翻译文本</td><td>翻译</td></tr><tr><td><code>Ctrl</code>+<code>Enter</code></td><td>检查文本</td><td>写作检查</td></tr><tr><td><code>Space</code></td><td>显示答案</td><td>抽认卡</td></tr><tr><td><code>1</code> … <code>4</code></td><td>评价卡片</td><td>抽认卡</td></tr></tbody></table><h2 id="鼠标手势-仅桌面" tabindex="-1">鼠标手势（仅桌面） <a class="header-anchor" href="#鼠标手势-仅桌面" aria-label="Permalink to &quot;鼠标手势（仅桌面）&quot;">​</a></h2><p>在释义区可以用两个鼠标手势切换标签。<strong>设置 → 其他</strong> 里能为每个手势分别选择动作：关闭、切换词典标签、切换单词标签。</p><table tabindex="0"><thead><tr><th>手势</th><th>操作</th><th>默认动作</th></tr></thead><tbody><tr><td>摇杆手势</td><td>按住<strong>左键</strong>，再点一下<strong>右键</strong></td><td>切到下一本词典标签</td></tr><tr><td>滚轮手势</td><td>按住<strong>左键</strong>，向上 / 向下滚动</td><td>切到上一个 / 下一个单词标签</td></tr></tbody></table><p>两个手势都从「按住左键」开始：接着点右键是摇杆手势，接着滚滚轮是滚轮手势，互不冲突。用左键而不是中键，是因为中键通常就是滚轮按下去，一边按住一边滚很难操作。</p><p>摇杆手势只做这一个方向：词典标签是循环切换的，多按几次转一圈就能回来，所以不需要反向。滚轮手势是双向的，适合在开了好几个词的单词标签之间来回找。</p><p><strong>展开式</strong>下没有词典标签，此时「切换词典标签」会自动退化为「切换单词标签」，不会按了没反应。</p><ul><li>只在 Windows、Linux、macOS 上生效；Android 没有右键和滚轮。</li><li>普通右键点击不受影响，只有左键按住时才会抑制右键菜单。macOS 的 <code>Ctrl</code>+左键是系统模拟的右键，不参与手势，仍走原来的行为。</li><li>滚轮手势做了节流，一次滚动不会连跳好几个标签；按住左键时页面自身的滚动会被阻止。</li><li>手势触发后紧随的那次点击会被拦掉，不会误开词条链接。</li></ul><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>分组与词典标签的快捷键只在释义页在前台时生效。</li><li>如果窗口管理器占用了 <code>Alt</code>+数字，就没法用这组键切换词典标签。</li><li><code>Ctrl</code>+<code>PgUp</code> 与 <code>Ctrl</code>+<code>PgDn</code> 切的是单词标签，<code>Alt</code>+<code>PgUp</code> 与 <code>Alt</code>+<code>PgDn</code> 切的是词典标签；单独按这两个键（不带修饰键）在展开式下用来翻页。</li><li>带修饰键的快捷键在释义区（原生 WebView）持有焦点时也能触发，不依赖焦点落在哪个控件上；裸 <code>PgUp</code>/<code>PgDn</code> 仍留给释义区滚动和输入框。</li><li>历史导航只用 <code>Alt</code>+<code>↑</code>/<code>↓</code>：macOS 的调度中心占用 <code>Ctrl</code>+<code>↑</code>/<code>↓</code>，KDE、GNOME、Windows 的窗口平铺占用 <code>Super</code>/<code>Win</code>+<code>↑</code>/<code>↓</code>，<code>Alt</code> 是主流桌面都留空的那一组。macOS 输入框里 <code>Option</code>+<code>↑</code>/<code>↓</code> 是「段落首 / 尾」，焦点在搜索框时词悦会让位给输入框。</li><li>桌面布局下，方向键用于在控件之间移动焦点，<code>Enter</code> 或 <code>Space</code> 激活当前聚焦的控件。</li></ul>`,46)]))}const u=d(a,[["render",r]]);export{b as __pageData,u as default};
